const nn = (...xs) => xs.every((x) => x !== null && x !== undefined);
function snapAt(rows, day) { // latest snapshot with filed < day
  let best = null;
  for (let i = 0; i < rows.length; i++) { if (rows[i][0] < day) best = rows[i]; else break; }
  return best;
}
const obj = (row) => { if (!row) return null; const o = {}; for (const k in COL) o[k] = row[COL[k]]; return o; };

export function rank(universe, t, ctx) {
  const day = t / 86400;
  const out = [];
  for (const sym of Object.keys(universe)) {
    const rows = D[sym];
    if (!rows) continue;
    const bars = universe[sym];
    const px = bars[bars.length - 1].close;
    const cur = snapAt(rows, day);
    if (!cur || day - cur[0] > ctx.params.stale) continue;
    const prv = snapAt(rows, day - 365);
    const r = obj(cur), p = obj(prv);
    if (!nn(r.sh) || !(r.sh > 0) || !(px > 0)) continue;
    const mc = px * r.sh;
    const s = (() => { return nn(r.ni) ? r.ni / mc : null; })();
    if (s !== null && s !== undefined) out.push([sym, s]);
  }
  const n = out.length;
  const w = {};
  if (n < ctx.params.minEligible) return w;
  out.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
  const m = Math.ceil(n * ctx.params.top);
  for (const [sym] of out.slice(0, m)) w[sym] = 1 / m;
  return w;
}
